class NativeStoreWalBootstrapFailureTransactionTest {

	@TempDir
	Path dataDir;

	@Test
	void failedAsyncBootstrapDoesNotPersistStatementsContextsOrNamespaces() throws Exception {
		var valueFactory = SimpleValueFactory.getInstance();
		IRI subject = valueFactory.createIRI("urn:subject");
		IRI predicate = valueFactory.createIRI("urn:predicate");
		IRI removedObject = valueFactory.createIRI("urn:removed-object");
		IRI retainedObject = valueFactory.createIRI("urn:retained-object");
		IRI newObject = valueFactory.createIRI("urn:new-object");
		IRI removedContext = valueFactory.createIRI("urn:removed-context");
		IRI retainedContext = valueFactory.createIRI("urn:retained-context");
		IRI newContext = valueFactory.createIRI("urn:new-context");
		IRI corruptTail = valueFactory.createIRI("urn:bootstrap-tail");

		seedLegacyStore(Map.of(
				"replace", "urn:old:",
				"remove", "urn:remove:",
				"keep", "urn:keep:"),
				valueFactory.createStatement(subject, predicate, removedObject, removedContext),
				valueFactory.createStatement(subject, predicate, retainedObject, retainedContext));
		addValuesAndCorruptTail(newObject, newContext, corruptTail);

		SailRepository repository = new SailRepository(new NativeStore(dataDir.toFile(), "spoc"));
		repository.init();
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				assertThatThrownBy(() -> {
					connection.setNamespace("replace", "urn:new:");
					connection.removeNamespace("remove");
					connection.setNamespace("added", "urn:added:");
					connection.clearNamespaces();
					connection.add(subject, predicate, newObject, newContext);
					connection.remove(subject, predicate, removedObject, removedContext);
					connection.commit();
				}).isInstanceOf(RepositoryException.class);
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				assertThat(connection.hasStatement(subject, predicate, removedObject, false, removedContext)).isTrue();
				assertThat(connection.hasStatement(subject, predicate, retainedObject, false, retainedContext))
						.isTrue();
				assertThat(connection.hasStatement(subject, predicate, newObject, false, newContext)).isFalse();
				assertThat(Iterations.asList(connection.getContextIDs()))
						.containsExactlyInAnyOrder(removedContext, retainedContext)
						.doesNotContain(newContext);
				assertThat(connection.getNamespace("replace")).isEqualTo("urn:old:");
				assertThat(connection.getNamespace("remove")).isEqualTo("urn:remove:");
				assertThat(connection.getNamespace("keep")).isEqualTo("urn:keep:");
				assertThat(connection.getNamespace("added")).isNull();
			}
		} finally {
			try {
				repository.shutDown();
			} catch (RepositoryException closeFailure) {
				// Shutdown re-reports the failed bootstrap after releasing the value-store files.
				assertThat(closeFailure).hasRootCauseInstanceOf(IOException.class);
			}
		}
	}

	@Test
	void failedAsyncBootstrapDoesNotCommitTransactionWithNewValueLsn() throws Exception {
		var valueFactory = SimpleValueFactory.getInstance();
		IRI subject = valueFactory.createIRI("urn:lsn-subject");
		IRI predicate = valueFactory.createIRI("urn:lsn-predicate");
		IRI existingObject = valueFactory.createIRI("urn:existing-object");
		IRI existingContext = valueFactory.createIRI("urn:existing-context");
		IRI newObject = valueFactory.createIRI("urn:new-object");
		IRI newContext = valueFactory.createIRI("urn:new-context");
		IRI corruptTail = valueFactory.createIRI("urn:lsn-bootstrap-tail");

		seedLegacyStore(Map.of(), valueFactory.createStatement(subject, predicate, existingObject, existingContext));
		addValuesAndCorruptTail(corruptTail);

		SailRepository repository = new SailRepository(new NativeStore(dataDir.toFile(), "spoc"));
		repository.init();
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				assertThatThrownBy(() -> {
					connection.add(subject, predicate, newObject, newContext);
					connection.commit();
				}).isInstanceOf(RepositoryException.class);
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				assertThat(connection.hasStatement(subject, predicate, existingObject, false, existingContext))
						.isTrue();
				assertThat(connection.hasStatement(subject, predicate, newObject, false, newContext)).isFalse();
				assertThat(Iterations.asList(connection.getContextIDs())).containsExactly(existingContext);
			}
		} finally {
			try {
				repository.shutDown();
			} catch (RepositoryException closeFailure) {
				// Shutdown re-reports the failed bootstrap after releasing the value-store files.
				assertThat(closeFailure).hasRootCauseInstanceOf(IOException.class);
			}
		}
	}

	private void seedLegacyStore(Map<String, String> namespaces, Statement... statements) throws Exception {
		NativeStore legacyStore = new NativeStore(dataDir.toFile(), "spoc");
		legacyStore.setWalEnabled(false);
		SailRepository legacyRepository = new SailRepository(legacyStore);
		legacyRepository.init();
		try {
			try (RepositoryConnection connection = legacyRepository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				namespaces.forEach(connection::setNamespace);
				for (Statement statement : statements) {
					connection.add(statement);
				}
				connection.commit();
			}
		} finally {
			legacyRepository.shutDown();
		}
	}

	private void addValuesAndCorruptTail(Value... values) throws Exception {
		try (ValueStore valueStore = new ValueStore(dataDir.toFile(), false)) {
			for (Value value : values) {
				valueStore.storeValue(value);
			}
			valueStore.sync();
		}
		makeLastStoredValueUnreadable();
	}

	private void makeLastStoredValueUnreadable() throws IOException {
		int maxId;
		try (DataStore dataStore = new DataStore(dataDir.toFile(), "values")) {
			maxId = dataStore.getMaxID();
		}
		try (RandomAccessFile ids = new RandomAccessFile(dataDir.resolve("values.id").toFile(), "r");
				RandomAccessFile data = new RandomAccessFile(dataDir.resolve("values.dat").toFile(), "rw")) {
			ids.seek((long) maxId * Long.BYTES);
			data.seek(ids.readLong());
			data.writeInt(-1);
		}
	}
}
